WITH base AS (SELECT *, INITCAP(TRIM(event_type)) AS event_type_title, CASE WHEN event_type IN ('search', 'add_to_cart') THEN 'Tier 1' ELSE 'Other' END AS event_type_group FROM web_events WHERE event_time >= TIMESTAMP '2023-10-15 11:00:00'), enriched AS (SELECT id, session_id, event_type, page, event_time, duration_sec, event_type_title, event_type_group, STDDEV_SAMP(duration_sec) OVER w_hist AS event_type_stddev_samp_duration_sec, SUM(duration_sec) OVER w_part AS duration_sec_sum_30d, STDDEV_SAMP(duration_sec) OVER (PARTITION BY page, event_type) AS page_stddev_samp_duration_sec, NTILE(5) OVER w_recent AS duration_sec_bucket FROM base WINDOW w_hist AS (PARTITION BY event_type, page), w_part AS (ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW), w_recent AS (ORDER BY duration_sec DESC, id)), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY duration_sec_sum_30d DESC, id) AS row_num FROM enriched QUALIFY row_num = 1), with_dims AS (SELECT src.*, p.country FROM deduped src LEFT JOIN sessions p ON src.session_id = p.id), valid AS (SELECT id, session_id, event_type, event_time, duration_sec, event_type_title, event_type_group, duration_sec_bucket, country, CASE WHEN page_stddev_samp_duration_sec >= 369 THEN 'High' WHEN page_stddev_samp_duration_sec >= 84 THEN 'Medium' ELSE 'Low' END AS page_stddev_samp_duration_sec_tier, DATE_FORMAT(event_time, 'MMM yyyy') AS event_time_label, COALESCE(page, 'UNKNOWN') AS page_clean FROM with_dims WHERE event_time >= TIMESTAMP '2023-12-11 12:00:00' AND page IS NOT NULL AND page_stddev_samp_duration_sec >= 400), scored AS (SELECT *, LEAD(duration_sec, 2, 0) OVER (PARTITION BY country ORDER BY duration_sec, id) AS next_duration_sec, FIRST_VALUE(duration_sec, TRUE) OVER (ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_duration_sec, RANK() OVER (ORDER BY duration_sec NULLS LAST) AS duration_sec_rank FROM valid), enriched_web_events AS (SELECT src.*, d.browser FROM scored src JOIN sessions d ON src.session_id = d.id), grouped AS (SELECT CASE WHEN duration_sec >= 530 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, session_id, CASE WHEN duration_sec_bucket >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_bucket_tier, MAX(next_duration_sec) FILTER (WHERE country = 'SG') AS sg_max_next_duration_sec, SIZE(COLLECT_SET(event_type)) AS num_event_types, AVG(first_known_duration_sec) FILTER (WHERE browser = 'Chrome') AS chrome_avg_first_known_duration_sec FROM enriched_web_events GROUP BY CASE WHEN duration_sec >= 530 THEN 'PREMIUM' ELSE 'STANDARD' END, session_id, CASE WHEN duration_sec_bucket >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END) SELECT s.duration_sec_tier, s.session_id, s.duration_sec_bucket_tier, s.sg_max_next_duration_sec, s.num_event_types, s.chrome_avg_first_known_duration_sec, (SELECT MAX(x.duration_sec) FROM web_events x WHERE x.session_id = s.session_id) AS max_web_event_duration_sec FROM grouped s ORDER BY max_web_event_duration_sec DESC NULLS FIRST, duration_sec_bucket_tier DESC
